mapper.select:
SELECT id, config_key, config_value, config_name, config_type, remark, status, create_time FROM sys_config WHERE deleted = 0
AND config_key LIKE CONCAT('%', #{configKey}, '%')
AND config_name LIKE CONCAT('%', #{configName}, '%')
AND status = #{status}
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET #{offset}

